/* Not a rejection: the card stays in the queue and the question goes out.
   Sending it is the app's job (one send layer), so this records the state and the
   question for that job to pick up. */
const b = $('Webhook').first().json.body;
return [{ json: { payload: { contribution_id: b.id, status: 'needs_detail',
  actor: b.actor }, question: b.question } }];

/* Evidence is required to reach 'consented' — the app refuses it without one, and
   the CHECK in 0001 refuses it again. */
const b = $('Webhook').first().json.body;
return [{ json: { payload: { caregiver_id: b.id, consent_status: b.to,
  evidence: b.to === 'consented'
    ? { method: b.method, note: b.note ?? null, at: new Date().toISOString() }
    : null,
  actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { caregiver_id: b.id, active: b.active ?? null,
  discoverable: b.discoverable ?? null, introducible: b.introducible ?? null,
  actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { pending_option_id: b.id, option_value: b.option_value,
  label: b.label, actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { flag_id: b.id, status: 'resolved', note: b.note ?? null,
  actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { demand_id: b.id, status: b.to, note: b.note ?? null,
  actor: b.actor } } }];

/* The override the question set allows: an exceptional firsthand caregiver
   nomination can qualify alone. Its reason goes into the audit row. */
const b = $('Webhook').first().json.body;
return [{ json: { payload: { person_id: b.ids[0], status: 'founding', actor: b.actor },
  override_reason: b.override_reason ?? null } }];

/* A hold exists because a parent hesitated about a named person. The reason is
   required, and it is what lands in the audit row. */
const b = $('Webhook').first().json.body;
return [{ json: { payload: { nomination_id: b.id, note: b.note, actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { flag_id: b.id, status: 'escalated', note: b.note ?? null,
  actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { pending_option_id: b.id, status: 'rejected',
  actor: b.actor } } }];

const b = $('Webhook').first().json.body;
return [{ json: { payload: { person_id: b.ids[0], status: 'request_invite',
  actor: b.actor } } }];

return [{ json: { ok: false, persisted: false,
  error: 'not_implemented',
  action: $('Webhook').first().json.body.action } }];
